import { prisma } from "@linkaffipro/db";
import { createOfferLink, dropUnsentOfferLink } from "./src/offer-link";
const url = process.env.DATABASE_URL ?? "";
if (!/localhost|127\.0\.0\.1/.test(url)) throw new Error("base non locale : refuse");
const persona = await prisma.persona.findFirst({ where: { affiliateCampaign: { isActive: true, NOT: { trackingUrlTemplate: "" } } }, select: { id: true } });
const conv = await prisma.conversation.findFirst({ select: { id: true, botId: true, memberId: true, source: true } });
console.log({ persona: !!persona, conv: !!conv });
if (persona && conv) {
  const link = await createOfferLink({ conversationId: conv.id, personaId: persona.id, botId: conv.botId, memberId: conv.memberId, source: conv.source });
  console.log("lien", link);
  if (link) {
    console.log("ligne", await prisma.assistantOfferLink.count({ where: { subId: link.subId } }));
    await dropUnsentOfferLink(link.subId);
    console.log("apres retrait", await prisma.assistantOfferLink.count({ where: { subId: link.subId } }));
  }
}
const none = await prisma.persona.findFirst({ where: { affiliateCampaignId: null }, select: { id: true } });
if (none && conv) console.log("sans offre", await createOfferLink({ conversationId: conv.id, personaId: none.id, botId: conv.botId, memberId: conv.memberId, source: null }));
await prisma.$disconnect();
EOF
